export const BODY: string = "\n<p>آپ کو تصویر یا اسکرین شاٹ میں مکمل رنگ ملا، اور اب اس کا کوڈ چاہیے۔ اندازہ لگانا وقت ضائع کرتا ہے، اور قریب غلط اصل کے ساتھ غلط لگتا ہے۔</p>\n<p>یہ رہنما چار عملی مراحل میں تصویر سے رنگ چننا بتاتا ہے۔ آپ تصویر اپ لوڈ کریں گے، میگنفائر سے نشانہ لیں گے، رنگ محفوظ کریں گے اور اسے اپنے پراجیکٹ کے لیے برآمد کریں گے۔</p>\n<p>ایک بار معلوم ہو جائے تو پورا عمل ایک منٹ سے کم لگتا ہے۔ انسٹال کرنے کو کوئی سافٹ ویئر نہیں، بنانے کو کوئی اکاؤنٹ نہیں، اور کسی سرور پر کوئی فائل اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے آپ کو کیا چاہیے</h2>\n<p>آپ کو وہ تصویر چاہیے جس میں رنگ ہے۔ تصویر، لوگو فائل، اسکرین شاٹ یا ڈیزائن موک اپ، سب کام کرتے ہیں، JPG، PNG، WebP یا GIF فارمیٹ میں۔</p>\n<p>فائل 20 MB تک ہو سکتی ہے، جو فون کی تصویروں اور اعلیٰ ریزولوشن اسکرین شاٹ کو آسانی سے پورا کرتی ہے۔ اگر آپ کی فائل بڑی ہو تو پہلے اسے کمپریس کریں یا تازہ اسکرین شاٹ لیں۔</p>\n<p>آپ کو براؤزر بھی چاہیے۔ ٹول کروم، سفاری، فائر فاکس اور ایج پر چلتا ہے، ڈیسک ٹاپ اور موبائل پر، بغیر کسی ایکسٹینشن یا پلگ ان کے۔</p>\n<h2 id=\"step-1-upload-or-paste\">مرحلہ 1: تصویر اپ لوڈ کریں یا اسکرین شاٹ چسپاں کریں</h2>\n<p><a href=\"/ur/tasveer-se-rang-chunein/\">تصویر رنگ پکر</a> کھولیں اور اپنی تصویر اپ لوڈ والے حصے میں گھسیٹ دیں۔ آپ اس حصے پر کلک کر کے اپنے آلے سے فائل بھی چن سکتے ہیں۔</p>\n<p>اگر رنگ ابھی آپ کی اسکرین پر ہے تو اسکرین شاٹ لیں اور ونڈوز پر Ctrl+V یا میک پر Cmd+V سے چسپاں کریں۔ ٹول کلپ بورڈ تصویریں سیدھی قبول کرتا ہے۔</p>\n<p>جیسے ہی تصویر لوڈ ہوتی ہے، وہ پکر میں دکھائی دیتی ہے۔ ایک رنگ فوراً دکھایا جاتا ہے، تصویر کے مرکز سے نمونہ لیا گیا، تاکہ آپ جان سکیں ٹول تیار ہے۔</p>\n<h2 id=\"step-2-aim-with-the-loupe\">مرحلہ 2: میگنفائر لوپ سے نشانہ لیں</h2>\n<p>اپنا کرسر تصویر پر منتقل کریں اور 11 بہ 11 میگنفائی شدہ لوپ دیکھیں۔ یہ آپ کے پوائنٹر کے گرد پکسل کا زوم شدہ گرڈ دکھاتا ہے، درمیان میں ہدف پکسل کے ساتھ۔</p>\n<p>جب آپ مطلوبہ رنگ کے قریب پہنچیں تو سست ہو جائیں۔ لوپ آپ کو شکل کے ٹھوس مرکز اور اس کے ملے ہوئے کنارے کے درمیان فرق دیکھنے دیتا ہے۔</p>\n<p>چپٹے حصے کے درمیان کا نشانہ لیں۔ بٹن، دیوار یا رنگ کا بلاک مرکز میں ٹھوس اور سرحدوں پر ملا ہوا ہوتا ہے، اس لیے مرکز صحیح قیمت دیتا ہے۔</p>\n<h2 id=\"step-3-click-to-save-the-swatch\">مرحلہ 3: سویچ محفوظ کرنے کے لیے کلک کریں</h2>\n<p>جب لوپ درست پکسل دکھائے تو اس پر کلک کریں۔ رنگ آپ کی Picked Swatches ٹرے میں شامل ہو جاتا ہے، اور اس کے کوڈ کاپی کرنے کے لیے دکھائے جاتے ہیں۔</p>\n<p>HEX کوڈ کاپی کرنے کے لیے اس پر کلک کریں۔ HEX وہ فارمیٹ ہے جو زیادہ تر لوگوں کو چاہیے، کیونکہ وہ سیدھا CSS، فگما، کینوا اور زیادہ تر ڈیزائن ٹول میں چسپاں ہوتا ہے۔</p>\n<p>صفحہ چھوڑنے سے پہلے آپ کو چاہیے ہر رنگ جمع کریں۔ مکمل سیٹ میں اسی تصویر سے اہم رنگ، ایکسنٹ، پس منظر اور متن رنگ شامل ہو سکتے ہیں۔</p>\n<h2 id=\"step-4-export-or-copy\">مرحلہ 4: CSS برآمد کریں یا کوڈ کاپی کریں</h2>\n<p>جب آپ کے سویچ مکمل ہوں تو Export CSS پر کلک کریں۔ ٹول آپ کے رنگ CSS کسٹم پراپرٹی کے طور پر فائل ڈاؤن لوڈ کرتا ہے، اسٹائل شیٹ میں چسپاں کرنے کے لیے تیار۔</p>\n<p>اگر صرف ایک رنگ چاہیے تو اس کا HEX کوڈ سیدھا انسپیکٹر سے کاپی کریں۔ یہ ایک قیمت کے لیے فائل ڈاؤن لوڈ کرنے سے تیز ہے۔</p>\n<p>پرنٹ کام کے لیے ہر چن کے لیے دکھائی گئی CMYK قیمتیں نوٹ کریں۔ وہ شروعاتی تخمینہ ہیں، مناسب تبدیلی سے پہلے پرنٹ ڈیزائنر کو بتانے کے لیے مفید۔</p>\n<h2 id=\"picking-from-a-photo\">تصویر سے رنگ چننا</h2>\n<p>تصویروں کو چپٹی گرافکس سے تھوڑا مختلف لمس چاہیے۔ کیمرہ شور اور JPEG کمپریشن کا مطلب ہے کہ پڑوسی پکسل مختلف ہیں، اس لیے ایک کلک شاذ ہی مکمل کہانی ہے۔</p>\n<p>اسی حصے کو تین یا چار بار نمونہ لیں، ہر بار ایک یا دو پکسل منتقل کریں۔ اگر کوڈ پہلے پانچ ہندسوں پر متفق ہوں تو آپ نے حقیقی رنگ پا لیا۔</p>\n<p>سب سے بڑے چپٹے حصے سے چنیں جو آپ ڈھونڈ سکتے ہیں۔ صاف آسمان، رنگا دروازہ یا ٹھوس قمیض بناوٹ والی سطح سے کہیں مستحکم پڑھنے دیتا ہے۔</p>\n<h2 id=\"picking-from-a-logo\">لوگو سے رنگ چننا</h2>\n<p>لوگو درست چاہتے ہیں، کیونکہ ایک ہندسہ غلط برانڈ رنگ پھر بھی غلط لگتا ہے۔ اپنے پاس سب سے اعلیٰ کوالٹی والی لوگو فائل سے شروع کریں، ترجیحاً PNG۔</p>\n<p>PNG فائلیں بالکل رنگ محفوظ رکھتی ہیں، اس لیے پڑھنے قابل اعتماد ہے۔ JPEG لوگو کمپریشن شور رکھتے ہیں، جو HEX کوڈ کا آخری ہندسہ بدل سکتا ہے۔</p>\n<p>لوگو میں سب سے بڑی چپٹی شکل کے مرکز کو نمونہ لیں۔ حرف یا بلاک کا درمیان ٹھوس ہوتا ہے، جبکہ کنارے پس منظر میں مل جاتے ہیں۔</p>\n<h2 id=\"picking-from-a-screenshot\">اسکرین شاٹ سے رنگ چننا</h2>\n<p>اسکرین شاٹ UI رنگوں کا تیز ترین ماخذ ہیں۔ اسکرین پکڑیں، Ctrl+V سے چسپاں کریں، اور بٹن، ہیڈر یا پس منظر کو سیدھا نمونہ لیں۔</p>\n<p>اسکرین شاٹ پر لوپ احتیاط سے استعمال کریں۔ انٹرفیس عناصر کے اینٹی ایلیاس کنارے ہیں، اس لیے سرحد پکسل عنصر اور پس منظر کا مرکب ہیں۔</p>\n<p>متن رنگوں کے لیے حرف کے سب سے موٹے حصے کو نمونہ لیں، جیسے بولڈ اسٹروک کا درمیان۔ پتلا متن زیادہ تر کنارے پکسل ہے، جو مرکب کے طور پر پڑھتے ہیں۔</p>\n<h2 id=\"picking-on-a-phone\">فون یا ٹیبلٹ پر رنگ چننا</h2>\n<p>ٹچ اسکرین پر آپ کلک کی بجائے ٹیپ کرتے ہیں، اور وہی لوپ اور سویچ ٹول لاگو ہوتے ہیں۔ اپنی گیلری سے تصویر اپ لوڈ کریں یا اسکرین شاٹ چسپاں کریں۔</p>\n<p>آپ کی انگلی کئی پکسل ڈھکتی ہے، اس لیے پہلے تصویر کو زوم کریں۔ بڑی تصویر آپ کو بڑا ہدف اور درست پکسل مارنے کا بہتر موقع دیتی ہے۔</p>\n<p>ٹیپ کرنے سے پہلے تصدیق کے لیے لوپ استعمال کریں۔ یہ دکھاتا ہے کہ آپ کی انگلی کے نیچے کیا ہے، جو آپ اپنی انگلی اسکرین پر ہونے کے دوران نہیں دیکھ سکتے۔</p>\n<h2 id=\"troubleshooting-wrong-colors\">مسئلہ حل کرنا: جب رنگ غلط لگے</h2>\n<p>اگر چنا ہوا رنگ بہت ہلکا یا بہت گہرا لگے تو آپ نے شاید جھلک یا سایہ نمونہ لیا۔ شکل کے درمیان کی طرف جائیں اور دوبارہ آزمائیں۔</p>\n<p>اگر رنگ کیچڑ لگے تو آپ نے شاید اینٹی ایلیاس کنارہ پکڑا۔ ایک یا دو پکسل اندر جائیں، جہاں رنگ ٹھوس اور غیر ملا ہے۔</p>\n<p>اگر ہر کلک پر HEX کوڈ بدلتا ہے تو حصہ شور والا ہے۔ قریبی کئی پکسل نمونہ لیں اور وہ قیمت استعمال کریں جو سب سے زیادہ بار دکھائی دے۔</p>\n<h2 id=\"using-the-color-in-your-project\">اپنے پراجیکٹ میں چنا ہوا رنگ استعمال کرنا</h2>\n<p>ویب سائٹ میں HEX کوڈ اپنی CSS میں چسپاں کریں یا برآمد شدہ کسٹم پراپرٹی استعمال کریں۔ متغیر طریقہ آپ کے رنگ پوری سائٹ پر مستقل رکھتا ہے۔</p>\n<p>فگما، کینوا یا فوٹوشاپ میں HEX کوڈ رنگ فیلڈ میں چسپاں کریں۔ ہر بڑا ڈیزائن ٹول HEX قبول کرتا ہے، اس لیے قیمت بغیر تبدیلی کے منتقل ہوتی ہے۔</p>\n<p>سلائیڈ ڈیک یا دستاویز کے لیے RGB قیمتیں استعمال کریں۔ آفس ٹول اکثر رنگ تین اعداد کے طور پر دکھاتے ہیں، اور RGB پڑھنے اس فارمیٹ سے بالکل میل کھاتا ہے۔</p>\n<h2 id=\"building-a-full-palette\">ایک تصویر سے مکمل پیلیٹ بنانا</h2>\n<p>ایک تصویر پوری پیلیٹ دے سکتی ہے۔ غالب پس منظر رنگ، اہم موضوع رنگ، ایک ایکسنٹ اور متن کے لیے گہرا لہجہ چنیں۔</p>\n<p>گنتی چھوٹی رکھیں۔ چار سے چھ رنگ زیادہ تر ڈیزائن کے لیے کافی ہیں، اور اس سے زیادہ عام طور پر لے آؤٹ کو بکھرا دکھاتا ہے۔</p>\n<p>برآمد سے پہلے سویچ کو ایک ساتھ جانچیں۔ اگر دو رنگ تقریباً ایک جیسے ہوں تو ایک ہٹا دیں۔ اگر سیٹ غیر متوازن لگے تو ایک چن کو ہلکے یا گہرے لہجے سے بدلیں۔</p>\n<h2 id=\"picking-from-charts\">چارٹ اور ڈیٹا ویژول سے رنگ چننا</h2>\n<p>چارٹ اور گراف رنگ استعمال کرتے ہیں ڈیٹا سیریز الگ کرنے کے لیے، اور ان رنگوں کو ملانا اہم ہے جب آپ اسی ڈیٹا کے گرد رپورٹ یا ڈیش بورڈ بنائیں۔ پکر چارٹ تصویر سے ہر سیریز رنگ واپس لا سکتا ہے۔</p>\n<p>ہر بار، لکیر یا پائی سلائس کے درمیان کو نمونہ لیں، کناروں سے دور جہاں رنگ پس منظر میں مل جاتے ہیں۔ موٹی بار نمونہ لینا آسان ہے، جبکہ پتلی لکیر کو مرکز مارنے کے لیے لوپ چاہیے۔</p>\n<p>پہلے لیجنڈ سے کام کریں، کیونکہ لیجنڈ عام طور پر ہر سیریز رنگ کو ٹھوس بلاک کے طور پر دکھاتا ہے۔ وہ بلاک پورے چارٹ میں صاف ترین نمونے ہیں۔</p>\n<h2 id=\"saving-and-organizing\">چنے ہوئے رنگ محفوظ اور منظم کرنا</h2>\n<p>چنے ہوئے رنگ صرف تب مفید ہیں جب آپ انہیں بعد میں ڈھونڈ سکیں۔ Export CSS ڈاؤن لوڈ سیٹ محفوظ کرنے کا آسان ترین طریقہ ہے، کیونکہ یہ ہر سویچ کو ایک فائل میں واضح متغیر ناموں کے ساتھ محفوظ کرتا ہے۔</p>\n<p>اپنی برآمد فائل کا نام پراجیکٹ کے حساب سے رکھیں، تاریخ کے حساب سے نہیں۔ homepage-refresh-colors.css جیسی فائل مہینوں بعد مفید ہے، جبکہ colors-2026-11-17.css آپ کو کچھ نہیں بتاتا کہ رنگ کہاں ہیں۔</p>\n<p>اگر آپ ڈیزائن ٹول استعمال کرتے ہیں تو HEX کوڈ اس کے رنگ سٹائل یا متغیر پینل میں بھی چسپاں کریں۔ ایک ہی قیمت کو اسٹائل شیٹ اور ڈیزائن فائل دونوں میں رکھنے سے دونوں الگ نہیں ہوتے۔</p>\n<h2 id=\"quick-reference-checklist\">فوری حوالہ چیک لسٹ</h2>\n<p>اپنے پاس صاف ترین اصل فائل اپ لوڈ کریں، اسکرین شاٹ کا اسکرین شاٹ نہیں۔ ہر اضافی محفوظ رنگ کو تھوڑا بدل سکتا ہے۔</p>\n<p>لوپ سے نشانہ لیں، چپٹے حصوں کے مرکز کو نمونہ لیں، اور قیمت کی تصدیق کے لیے دو یا تین قریبی پکسل پر کلک کریں۔</p>\n<p>ویب اور ڈیزائن کام کے لیے HEX کوڈ کاپی کریں، دستاویزات کے لیے RGB قیمتیں، اور پرنٹ بریف کے لیے CMYK تخمینہ۔</p>\n<p>جب ایک سے زیادہ سویچ ہوں تو CSS برآمد کریں، اور اس پر بنانے سے پہلے اپنے پراجیکٹ میں رنگ کی تصدیق کریں۔ مکمل پس منظر کے لیے <a href=\"/ur/blog/tasveer-color-picker-rehnumai/\">Image Color Picker: Complete Guide</a> پڑھیں اور کوڈ فارمیٹ موازنہ <a href=\"/ur/blog/hex-vs-rgb-vs-hsl/\">HEX vs RGB vs HSL: Colour Codes Explained</a> میں دیکھیں۔</p>\n";

